CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_asistenciaxclase` (IN `an_cod_horario` INT(10), IN `an_cod_clase` INT(3), IN `an_cod_instructor` INT(5), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  SELECT an_cod_horario, an_cod_clase, t.n_cod_estudiante, an_cod_instructor, '0', as_cod_usuario, NOW() 
  FROM MOV_MATRICULA t 
  WHERE t.n_cod_horario = an_cod_horario
    AND t.v_flag_estado = '1'
    AND not exists (SELECT 1 
                      FROM MOV_ASISTENCIA x 
                     WHERE x.n_cod_horario    = t.n_cod_horario
                       AND x.n_clase          = an_cod_clase
                       AND x.n_cod_estudiante = t.n_cod_estudiante);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_estudiantesede` (IN `an_cod_traslado` INT(10), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  -- Declarar variables
  DECLARE li_cod_estudiante int;
  DECLARE li_cod_sede int;
  -- Capturar datos
  SELECT t.N_COD_ESTUDIANTE, t.N_COD_SEDE_DESTINO INTO li_cod_estudiante, li_cod_sede FROM MOV_TRASLADO t WHERE t.N_COD_TRASLADO  = an_cod_traslado;
  -- Insertar Histórico
  SELECT t.N_COD_ESTUDIANTE, t.D_FEC_INICIO, t.D_FEC_FIN, t.N_COD_SEDE_ORIGEN, t.N_COD_SEDE_DESTINO, '1', as_cod_usuario, NOW() FROM MOV_TRASLADO t 
  WHERE t.N_COD_TRASLADO  = an_cod_traslado 
    AND not exists (SELECT * FROM MAE_ESTUDIANTE_SEDE x 
                     WHERE x.N_COD_ESTUDIANTE = t.N_COD_ESTUDIANTE
                       AND x.D_FEC_INICIO = t.D_FEC_INICIO
                       );
  -- Actualizar Maestro
  UPDATE MAE_ESTUDIANTE E SET E.N_COD_SEDE = li_cod_sede WHERE E.N_COD_ESTUDIANTE = li_cod_estudiante;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_evaluacion_det` (IN `an_cod_evaluacion` INT(10), IN `an_cod_examen` INT(10), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  SELECT an_cod_evaluacion, t.n_cod_examen, t.n_item, t.v_descripcion, t.n_peso, t.n_minimo, '1', as_cod_usuario, NOW() 
  FROM MAE_EXAMEN_DET t 
  WHERE t.n_cod_examen = an_cod_examen
  AND t.v_flag_estado = '1';
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_hist_cinturon` (IN `an_cod_estudiante` INT(10), IN `an_cod_cinturon` INT(5), IN `as_marca` VARCHAR(1), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  -- Declarar variables
  DECLARE li_cuenta int;
  DECLARE li_orden int;
  -- Contar Cinturones 
  SELECT COUNT(1) INTO li_cuenta 
    FROM MAE_ESTUDIANTE_CINTURON e 
   WHERE e.N_COD_ESTUDIANTE = an_cod_estudiante
     AND e.N_COD_CINTURON = an_cod_cinturon
     AND e.V_FLAG_ESTADO = '1';
  -- Si existe Limpiar
  IF li_cuenta > 0 THEN
    DELETE FROM MAE_ESTUDIANTE_CINTURON WHERE N_COD_ESTUDIANTE = an_cod_estudiante AND N_COD_CINTURON = an_cod_cinturon;
  END IF;
  -- Si está marcado inserta
  IF as_marca = '1' THEN
    -- Orden
    SELECT e.n_orden INTO li_orden
    FROM MAE_CINTURON e 
   WHERE e.N_COD_CINTURON = an_cod_cinturon;
    -- Insertar Cinturon
    IF li_cuenta = 0 THEN
        VALUES (an_cod_estudiante, an_cod_cinturon, li_orden, '1', as_cod_usuario, NOW() );
    END IF;
  END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_horarioayudante` (IN `an_cod_horario` INT(10), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  -- Declarar variables
  DECLARE li_cod_sede int;
  DECLARE li_cod_instructor int;
  -- Capturar Sede
  SELECT h.n_cod_sede, h.n_cod_instructor INTO li_cod_sede, li_cod_instructor
    FROM MOV_HORARIO h
   WHERE h.n_cod_horario = an_cod_horario;
  -- Insertar
  SELECT an_cod_horario, t.n_cod_instructor, '0', as_cod_usuario, NOW() 
  FROM MAE_SEDE_INSTRUCTOR t 
  WHERE t.n_cod_sede = li_cod_sede
    AND t.n_cod_instructor <> li_cod_instructor
    AND not exists (SELECT * FROM MOV_HORARIO_AYUDANTE x 
                    WHERE x.n_cod_instructor = t.n_cod_instructor and x.n_cod_horario = an_cod_horario);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_progclases` (IN `an_cod_horario` INT(10), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  -- Declarar variables
  DECLARE li_sesion int DEFAULT 0; 
  DECLARE ld_fec_inicio date;
  DECLARE ld_fec_clase  date;
  DECLARE ldt_hora_inicio time;
  DECLARE li_horas int;
  DECLARE li_sesiones int;
  DECLARE li_cod_instructor int; 
  DECLARE ls_fg_1 varchar(1);
  DECLARE ls_fg_2 varchar(1);
  DECLARE ls_fg_3 varchar(1);
  DECLARE ls_fg_4 varchar(1);
  DECLARE ls_fg_5 varchar(1);
  DECLARE ls_fg_6 varchar(1);
  DECLARE ls_fg_7 varchar(1);
  DECLARE li_diaSem int DEFAULT 0; 
  DECLARE li_dia_1 int DEFAULT 0; 
  DECLARE li_dia_2 int DEFAULT 0; 
  DECLARE li_dia_3 int DEFAULT 0; 
  DECLARE li_dia_4 int DEFAULT 0; 
  DECLARE li_dia_5 int DEFAULT 0; 
  DECLARE li_dia_6 int DEFAULT 0;
  DECLARE li_dia_7 int DEFAULT 0;   
  -- Obtener datos de horario
  SELECT h.D_FEC_INICIO, h.D_HORA_INICIO, h.N_HORAS, h.N_SESIONES, N_COD_INSTRUCTOR,
         h.V_FLAG_DIA_1, h.V_FLAG_DIA_2, h.V_FLAG_DIA_3, 
         h.V_FLAG_DIA_4, h.V_FLAG_DIA_5, h.V_FLAG_DIA_6, h.V_FLAG_DIA_7
    INTO ld_fec_inicio, ldt_hora_inicio, li_horas, li_sesiones, li_cod_instructor,
         ls_fg_1, ls_fg_2, ls_fg_3, ls_fg_4, ls_fg_5, ls_fg_6, ls_fg_7
    FROM MOV_HORARIO h
   WHERE h.N_COD_HORARIO = an_cod_horario;
  -- Capturar Días Programados
  IF (ls_fg_1 = '1') THEN
    SET li_dia_1 = 1;
  END IF;
  IF (ls_fg_2 = '1') THEN
    SET li_dia_2 = 2;
  END IF;
  IF (ls_fg_3 = '1') THEN
    SET li_dia_3 = 3;
  END IF;
  IF (ls_fg_4 = '1') THEN
    SET li_dia_4 = 4;
  END IF;
  IF (ls_fg_5 = '1') THEN
    SET li_dia_5 = 5;
  END IF;
  IF (ls_fg_6 = '1') THEN
    SET li_dia_6 = 6;
  END IF;
  IF (ls_fg_7 = '1') THEN
    SET li_dia_7 = 7;
  END IF;
  -- Inicializar
  SET ld_fec_clase = ld_fec_inicio;
  -- Bucle de Sesiones
  WHILE (li_sesiones > li_sesion) DO
    -- Capturar Día
    SELECT DAYOFWEEK(ld_fec_clase) INTO li_diaSem;
    -- Si es Día
    IF ( li_diaSem = li_dia_1 OR li_diaSem = li_dia_2 OR li_diaSem = li_dia_3 
       OR li_diaSem = li_dia_4 OR li_diaSem = li_dia_5 OR li_diaSem = li_dia_6 
       OR li_diaSem = li_dia_7 ) THEN
      -- Incrementar Sesión
      SET li_sesion = li_sesion + 1;
      -- Insertar Fila Clase 
      VALUES (an_cod_horario, li_sesion, li_cod_instructor, ld_fec_clase, ldt_hora_inicio, li_horas, 'Generado automaticamente', '1', as_cod_usuario, NOW() );
    END IF;
    -- Incrementar Fecha
    SET ld_fec_clase = ld_fec_clase + 1;    
  END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_progevento` (IN `an_cod_evento` INT(10), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  SELECT an_cod_evento, t.n_cod_estudiante, '0', '0', as_cod_usuario, NOW() 
  FROM MAE_ESTUDIANTE t 
  WHERE t.v_tipo_est = 'EST_INT'
    AND not exists (SELECT * FROM MOV_EVENTO_PROG x 
                    WHERE x.n_cod_estudiante = t.n_cod_estudiante and x.n_cod_evento = an_cod_evento);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_rolopcion` (IN `as_cod_rol` VARCHAR(20), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  SELECT as_cod_rol, t.n_cod_opcion, '0', as_cod_usuario, NOW() FROM MAE_MENU_OPCION t 
  WHERE not exists (SELECT * FROM MAE_ROL_OPCION x 
                    WHERE x.n_cod_opcion = t.n_cod_opcion and x.v_cod_rol = as_cod_rol);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_rolusuario` (IN `as_cod_rol` VARCHAR(20), IN `as_cod_tipouser` VARCHAR(10), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  SELECT as_cod_rol, t.v_cod_user, t.v_cod_tipo, '0', as_cod_usuario, NOW() FROM MAE_USUARIO t 
  WHERE t.v_cod_tipo = as_cod_tipouser 
    AND not exists (SELECT * FROM MAE_ROL_USUARIO x 
                     WHERE x.v_cod_user = t.v_cod_user 
                       AND x.v_cod_tipouser = as_cod_tipouser
                       AND x.v_cod_rol = as_cod_rol
                       );
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_sedeinstructor` (IN `an_cod_sede` INT(5), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  SELECT an_cod_sede, t.n_cod_instructor, '0', as_cod_usuario, NOW() 
  FROM MAE_INSTRUCTOR t 
  WHERE not exists (SELECT * FROM MAE_SEDE_INSTRUCTOR x 
                    WHERE x.n_cod_instructor = t.n_cod_instructor and x.n_cod_sede = an_cod_sede);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generar_usuario` (IN `as_cod_tipouser` VARCHAR(10), IN `an_cod_referencia` INT(10), IN `as_clave` VARCHAR(60), IN `as_cod_usuario` VARCHAR(10))   BEGIN
  -- Declarar variables
  DECLARE li_cuenta int;
  DECLARE ls_nro_doc varchar(40);
  DECLARE ls_datos varchar(100);
  DECLARE ls_email varchar(40); 
  DECLARE ls_foto varchar(150); 
  -- Consultar si existe usuario (Evaluarlo)
  SELECT COUNT(1) INTO li_cuenta 
    FROM MAE_USUARIO u
   WHERE u.V_COD_TIPO = as_cod_tipouser
     AND u.N_COD_REFERENCIA = an_cod_referencia;
  -- No existe Usuario
  IF li_cuenta = 0 THEN
    -- Capturar datos segun caso
    IF as_cod_tipouser = 'EST_INT' OR as_cod_tipouser = 'EST_EXT' THEN
      SELECT e.V_NRO_DOC, CONCAT_WS(' ', e.V_APE_PATERNO, e.V_APE_MATERNO, e.V_NOMBRES) as datos, e.V_EMAIL, e.V_FOTO 
        INTO ls_nro_doc, ls_datos, ls_email, ls_foto
        FROM MAE_ESTUDIANTE e
       WHERE e.N_COD_ESTUDIANTE = an_cod_referencia;
    ELSE
      SELECT i.V_NRO_DOC, CONCAT_WS(' ', i.V_APE_PATERNO, i.V_APE_MATERNO, i.V_NOMBRES) as datos, i.V_EMAIL, i.V_FOTO -- USER_INST
        INTO ls_nro_doc, ls_datos, ls_email, ls_foto
        FROM MAE_INSTRUCTOR i
       WHERE i.N_COD_INSTRUCTOR = an_cod_referencia;
    END IF;
  	-- Insertar Usuario
      VALUES (ls_nro_doc, ls_datos, ls_email, as_clave, ls_foto, CURDATE(), as_cod_tipouser, an_cod_referencia, 'Generado automaticamente', '1', as_cod_usuario, NOW() );
   END IF;
END$$

