INSERT INTO `MAE_CINTURON` (`N_COD_CINTURON`, `N_COD_TIPOGRADO`, `V_DES_LARGA`, `V_DES_CORTA`, `V_COD_COLOR`, `V_TEXTO`, `N_ORDEN`, `V_FOTO`, `V_FLAG_ESTADO`, `V_AUD_USR_REG`, `D_AUD_FEC_REG`, `V_AUD_USR_MOD`, `D_AUD_FEC_MOD`) VALUES
(00001, 1, 'Cinturón Blanco', 'Blanco', '#fdfcfc', 'Este color simboliza la inocencia, el inicio del practicante en el camino del Taekwondo.', 1, 'Judo_white_belt.svg.png', '1', 'admweb', '2023-04-17 03:34:30', NULL, NULL),
(00002, 1, 'Cinturón Blanco c/ Punta Amarilla', 'Blanco con Punta Amarilla', '#f8f7f7', 'Esta combinación simboliza la semilla del taekwondo, sembrada en el practicante.', 2, 'Tkd_9th_kup.svg.png', '1', 'admweb', '2023-04-17 03:36:14', NULL, NULL),
(00003, 1, 'Cinturón Amarillo', 'Amarillo', '#f9d801', 'Este color simboliza la tierra fértil, donde se plantará una nueva semilla que brotará como una futura planta.', 3, 'Judo_yellow_belt.svg.png', '1', 'admweb', '2023-04-17 03:46:32', NULL, NULL),
(00004, 1, 'Cinturón Amarillo con Punta Verde', 'Amarillo con Punta Verde', '#f7cf02', 'Esta combinación simboliza la germinación de la semilla, como una nueva planta.', 4, 'Tkd_7th_kup.svg.png', '1', 'admweb', '2023-04-17 03:47:36', NULL, NULL),
(00005, 1, 'Cinturón Verde', 'Verde', '#02e31d', 'Este color simboliza el crecimiento de la planta, a medida que las habilidades en el Taekwondo comienzan a desarrollarse.', 5, 'Judo_green_belt.svg.png', '1', 'admweb', '2023-04-17 03:48:38', NULL, NULL),
(00006, 1, 'Cinturón Verde con Punta Azul', 'Verde con Punta Azul', '#42da01', 'Esta combinación representa a la planta buscando su punto de maduración en su crecimiento.', 6, 'Tkd_5th_kup.svg.png', '1', 'admweb', '2023-04-17 03:49:42', NULL, NULL),
(00007, 1, 'Cinturón Azul', 'Azul', '#0531e1', 'Simboliza el Cielo, hacia el cual va creciendo la planta hasta convertirse en un árbol maduro, a medida que los conocimientos en Taekwondo avanzan.', 7, 'Judo_blue_belt.svg.png', '1', 'admweb', '2023-04-17 03:50:38', NULL, NULL),
(00008, 1, 'Cinturón Azul con Punta Roja', 'Azul con Punta Roja', '#042dd2', 'Esta combinación simboliza a los primeros frutos que el árbol comienza a dar, los cuales son los frutos logrados en el aprendizaje del Taekwondo.', 8, 'Tkd_3rd_kup.svg.png', '1', 'admweb', '2023-04-17 03:51:50', NULL, NULL),
(00009, 1, 'Cinturón Rojo', 'Rojo', '#f90101', 'Este color simboliza el peligro. Es la etapa en la cual el estudiante debe aprender a manejar la cautela para medir su fuerza ante sus oponentes. Al mismo tiempo, indica a sus oponentes que deben mantenerse alejados, debido a la madurez de sus conocimientos. Otro significado, es el fruto cosechado del árbol del Taekwondo.', 9, 'Judo_red_belt.svg.png', '1', 'admweb', '2023-04-17 03:52:45', NULL, NULL),
(00010, 1, 'Cinturón Rojo con Punta Negra', 'Rojo con Punta Negra', '#e60000', 'Esta combinación simboliza la transición del estudiante en su paso de alumno a instructor. En este grado, el alumno comienza a preparar su graduación como instructor.', 10, 'Tkd_1st_kup.svg.png', '1', 'admweb', '2023-04-17 03:53:51', NULL, NULL),
(00011, 1, 'Cinturón 1 Grado Poom', '1 Poom', '#e60000', 'Esta combinación simboliza la transición del estudiante en su paso de alumno a instructor. En este grado, el alumno comienza a preparar su graduación como instructor.', 11, 'Tkd_1st_kup.svg.png', '1', 'admweb', '2023-04-17 03:53:51', '71997739', '2025-01-28 04:18:55'),
(00012, 1, 'Cinturón 2 Grado Poom', '2  Poom', '#e60000', 'Esta combinación simboliza la transición del estudiante en su paso de alumno a instructor. En este grado, el alumno comienza a preparar su graduación como instructor.', 12, 'Tkd_1st_kup.svg.png', '1', 'admweb', '2023-04-17 03:53:51', '71997739', '2025-01-28 04:19:10'),
(00013, 1, 'Cinturón 3 Grado Poom', '3  Poom', '#e60000', 'Esta combinación simboliza la transición del estudiante en su paso de alumno a instructor. En este grado, el alumno comienza a preparar su graduación como instructor.', 13, 'Tkd_1st_kup.svg.png', '1', 'admweb', '2023-04-17 03:53:51', '71997739', '2025-01-28 04:19:29'),
(00014, 2, 'Cinturón Negro 1 Grado Dan', '1 Grado Dan', '#000000', 'Este color simboliza la madurez del practicante en cuanto a su competencia para impartir enseñanza en el Taekwondo. Es completamente lo opuesto al color blanco. Una representación que tiene el negro, es en el carbón, por su dureza y sencillez, el cual puede arder para generar energía o desintegrarse para escribir su historia. Representa también la impermeabilidad de su portador, al miedo y la oscuridad.', 14, '55px-ITF_1_DAN_belt.png', '1', 'admweb', '2023-04-17 03:55:14', 'admweb', '2023-04-17 03:57:02'),
(00015, 2, 'Cinturón Negro 2 Grado Dan', '2 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Instructor Asistente (Boo Sabom Nim).', 15, '55px-ITF_1_DAN_belt_1.png', '1', 'admweb', '2023-04-17 03:56:34', NULL, NULL),
(00016, 2, 'Cinturón Negro 3 Grado Dan', '3 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Instructor Asistente (Boo Sabom Nim).', 16, '55px-ITF_1_DAN_belt_2.png', '1', 'admweb', '2023-04-17 03:57:47', NULL, NULL),
(00017, 2, 'Cinturón Negro 4 Grado Dan', '4 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Instructor Internacional (Sabom Nim).', 17, '55px-ITF_1_DAN_belt_3.png', '1', 'admweb', '2023-04-17 03:58:32', NULL, NULL),
(00018, 2, 'Cinturón Negro 5 Grado Dan', '5 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Instructor Mayor (Sabom Nim).', 18, '55px-ITF_1_DAN_belt_4.png', '1', 'admweb', '2023-04-17 03:59:03', NULL, NULL),
(00019, 2, 'Cinturón Negro 6 Grado Dan', '6 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Instructor Mayor (Sabom Nim).', 19, '55px-ITF_1_DAN_belt_5.png', '1', 'admweb', '2023-04-17 03:59:43', NULL, NULL),
(00020, 2, 'Cinturón Negro 7 Grado Dan', '7 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Master o Maestro (Sajiong Nim). Es el último título entregado a través de examen de graduación.', 20, '55px-ITF_1_DAN_belt_6.png', '1', 'admweb', '2023-04-17 04:00:16', NULL, NULL),
(00021, 2, 'Cinturón Negro 8 Grado Dan', '8 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Master Senior (Sajiong Nim). Es el primero de dos títulos que se entregan de forma honorífica.', 21, '55px-ITF_1_DAN_belt_7.png', '1', 'admweb', '2023-04-17 04:00:58', NULL, NULL),
(00022, 2, 'Cinturón Negro 9 Grado Dan', '9 Grado Dan', '#000000', 'Quien sea portador de este grado, será conocido con el título de Gran Maestro (Sasong Nim). Es el segundo y último título que se entrega en forma honorífica, por lo tanto, es la máxima graduación a la que un practicante de Taekwondo puede aspirar.', 22, '55px-ITF_1_DAN_belt_8.png', '1', 'admweb', '2023-04-17 04:01:44', NULL, NULL);
