(0000000477, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 15.00, 'Se observa, escapulas derecha  e izquierda alada, leve.', '1', '42492038', '2024-04-21 16:40:58', '47731989', '2024-04-22 05:13:35'),
(0000000477, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 10.00, 'Se observa, un leve descenso en el hombro izquierdo.', '1', '42492038', '2024-04-21 16:40:58', '47731989', '2024-04-22 05:13:35'),
(0000000477, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 3.00, 'Se observa, la cabeza en proyección  anterior leve, en la columna vertebral una cifolordosis leve, en la pelvis una anteversión leve.', '1', '42492038', '2024-04-21 16:40:58', '47731989', '2024-04-22 05:13:35'),
(0000000477, 0000000008, 4, 'OBSERVACION Y RECOMENDACION', 0.00, 0.00, 0.00, 'Se recomienda,  el uso de corrector postural adecuado para su edad,  y realizar  ejercicios de estiramientos para fortalecer los músculos  de la columna. Asimismo ejercicios para fortalecer los músculos de la pierna. Evitar el excesivo peso de la mochila.', '1', '42492038', '2024-04-21 16:40:58', '47731989', '2024-04-22 05:13:35'),
(0000000478, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, escapula derecha e izquierda abducida levemente.', '1', '42492038', '2024-04-21 17:30:36', '47731989', '2024-04-27 05:23:10'),
(0000000478, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, clavícula derecha en eleve descenso, hombro derecho en leve descenso, rodillas en valgo leve.', '1', '42492038', '2024-04-21 17:30:36', '47731989', '2024-04-27 05:23:10'),
(0000000478, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'Se observa, cabeza en proyección posterior ligeramente, columna vertebral en lordosis leve, pelvis en anteversión leve.', '1', '42492038', '2024-04-21 17:30:36', '47731989', '2024-04-27 05:23:10'),
(0000000478, 0000000008, 4, 'RECOMENDACION', 20.00, 0.00, 0.00, 'Se recomienda, ejercicios y estiramientos para la columna, estiramiento de los músculos de la cadera. Evitar  posturas inadecuadas. Llevar la mochila de manera adecuada sin exceder el peso.', '1', '42492038', '2024-04-21 17:30:36', '47731989', '2024-04-27 05:23:10'),
(0000000479, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, escapula abducida leve el lado derecho.', '1', '42492038', '2024-04-21 17:31:05', '47731989', '2024-04-23 01:13:49'),
(0000000479, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, cabeza en inclinación leve el lado derecho, hombro derecho en leve descenso. ', '1', '42492038', '2024-04-21 17:31:05', '47731989', '2024-04-23 01:13:49'),
(0000000479, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'se observa, cabeza en proyección anterior  leve, columna vertebral cifosis leve.', '1', '42492038', '2024-04-21 17:31:05', '47731989', '2024-04-23 01:13:49'),
(0000000479, 0000000008, 4, 'RECOMENDACION', 20.00, 0.00, 0.00, 'se recomienda ejercicios y estiramientos, para fortalcer los músculos de la columna, evitar peso excesivo de la mochila.', '1', '42492038', '2024-04-21 17:31:05', '47731989', '2024-04-23 01:13:49'),
(0000000480, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, en cabeza una leve inclinación  izquierda, en la escapula derecha y izquierda alada.se observa', '1', '42492038', '2024-04-21 17:31:28', '47731989', '2024-04-30 10:04:54'),
(0000000480, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, en la actitud corporal, una ligera inclinación lateral  izquierda.', '1', '42492038', '2024-04-21 17:31:28', '47731989', '2024-04-30 10:04:54'),
(0000000480, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'Se observa, la actitud corporal derecha con una ligera inclinación anterior.', '1', '42492038', '2024-04-21 17:31:28', '47731989', '2024-04-30 10:04:54'),
(0000000480, 0000000008, 4, 'RECOMENDACION', 20.00, 0.00, 0.00, 'Se recomienda, ejercicios y estiramientos para fortalecer los músculos de la espalda. Llevar la mochila adecuadamente sin exceder el peso, para evitar alteraciones posturales.', '1', '42492038', '2024-04-21 17:31:28', '47731989', '2024-04-30 10:04:54'),
(0000000481, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, la escapula derecha levemente abducida, pie izquierdo en valgo levemente.', '1', '42492038', '2024-04-21 17:32:08', '47731989', '2024-04-23 12:33:45'),
(0000000481, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, cabeza en leve inclinación derecha, hombro en leve descenso, rodilla derecha e izquierda en valgo.', '1', '42492038', '2024-04-21 17:32:08', '47731989', '2024-04-23 12:33:45'),
(0000000481, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'Se observa, cabeza levemente en proyección anterior.', '1', '42492038', '2024-04-21 17:32:08', '47731989', '2024-04-23 12:33:45'),
(0000000481, 0000000008, 4, 'RECOMENDACION', 20.00, 0.00, 0.00, 'Se recomienda,  fortalecer músculos de la espalda, asimismo fortalecer músculos de la piernas. ', '1', '42492038', '2024-04-21 17:32:08', '47731989', '2024-04-23 12:33:45'),
(0000000482, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, escapula derecha e izquierda levemente aducida.', '1', '42492038', '2024-04-21 17:32:33', '47731989', '2024-04-22 03:12:08'),
(0000000482, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, hombro derecho  levemente descendido.', '1', '42492038', '2024-04-21 17:32:33', '47731989', '2024-04-22 03:12:08'),
(0000000482, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'Se observa, en la columna vertebral espalda plana leve.', '1', '42492038', '2024-04-21 17:32:33', '47731989', '2024-04-22 03:12:08'),
(0000000482, 0000000008, 4, 'RECOMENDACION', 20.00, 0.00, 0.00, 'Se recomienda, fortalecer los músculos de la espalda. ', '1', '42492038', '2024-04-21 17:32:33', '47731989', '2024-04-22 03:12:08'),
(0000000483, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, hombro izquierdo en leve descenso.', '1', '42492038', '2024-04-21 17:33:10', '47731989', '2024-04-23 01:04:42'),
(0000000483, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, escapula derecha e  izquierda elevada levemente.', '1', '42492038', '2024-04-21 17:33:10', '47731989', '2024-04-23 01:04:42'),
(0000000483, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'Se observa, la actitud corporal inclinación anterior leve.', '1', '42492038', '2024-04-21 17:33:10', '47731989', '2024-04-23 01:04:42'),
(0000000483, 0000000008, 4, 'RECOMENDACION', 20.00, 0.00, 0.00, 'Se recomienda, uso adecuado de la mochila no exceder el peso, equilibrar  ambos hombros.', '1', '42492038', '2024-04-21 17:33:10', '47731989', '2024-04-23 01:04:42'),
(0000000484, 0000000008, 1, 'VISTA POSTERIOR', 20.00, 0.00, 0.00, 'Se observa, la actitud corporal en inclinación lateral derecha, escapula izquierda descendida, columna vertebral escoliosis dorsal leve.', '1', '42492038', '2024-04-21 17:33:36', '47731989', '2024-04-23 12:53:09'),
(0000000484, 0000000008, 2, 'VISTA ANTERIOR', 20.00, 0.00, 0.00, 'Se observa, cabeza en inclinación al lado derecho leve, hombro derecho en descenso leve. ', '1', '42492038', '2024-04-21 17:33:36', '47731989', '2024-04-23 12:53:09'),
(0000000484, 0000000008, 3, 'VISTA LATERAL', 20.00, 0.00, 0.00, 'Se observa, cabeza en proyección anterior, columna vertebral en lordosis, pelvis en anteversión leve.', '1', '42492038', '2024-04-21 17:33:36', '47731989', '2024-04-23 12:53:09'),
